.luminous-card-container {
  box-sizing: border-box;
  scroll-behavior: smooth;
  margin: 0;
  padding: 0;
  --sz: clamp(17px, min(2%, 3%), 24px);
  font-size: var(--sz);
  display: grid;
  place-items: center;
  background: #1e1e1e;
  background: radial-gradient(circle at 50% 30%, #2a2a2a 0%, #131313 64%);
  font-family: "Aeonik Pro Regular", sans-serif;
  min-height: 100%;
  overflow: hidden;
  min-width: 100%;
}

.luminous-card-container * {
  box-sizing: border-box;
}

.luminous-card {
  position: relative;
  background: radial-gradient(circle at 50% 0%, #3a3a3a 0%, #1a1a1a 64%);
  box-shadow:
    inset 0 1.01rem 0.2rem -1rem #fff0,
    inset 0 -1.01rem 0.2rem -1rem #0000,
    0 -1.02rem 0.2rem -1rem #fff0,
    0 1rem 0.2rem -1rem #0000,
    0 0 0 1px #fff3,
    0 4px 4px 0 #0004,
    0 0 0 1px #333;
  width: 18rem;
  height: 24rem;
  border-radius: 1.8rem;
  color: #fff;
  padding: 1rem;
  display: flex;
  flex-direction: column;
  justify-content: end;
  transition:
    all 0.4s ease-in-out,
    translate 0.4s ease-out;
}

.luminous-card::before {
  content: "";
  display: block;
  --offset: 1rem;
  width: calc(100% + 2 * var(--offset));
  height: calc(100% + 2 * var(--offset));
  position: absolute;
  left: calc(-1 * var(--offset));
  right: calc(-1 * var(--offset));
  top: calc(-1 * var(--offset));
  bottom: calc(-1 * var(--offset));
  margin: auto;
  box-shadow: inset 0 0 0px 0.06rem #fff2;
  border-radius: 2.6rem;
  --ax: 4rem;
  clip-path: polygon(
    var(--ax) 0,
    0 0,
    0 var(--ax),
    var(--ax) var(--ax),
    var(--ax) calc(100% - var(--ax)),
    0 calc(100% - var(--ax)),
    0 100%,
    var(--ax) 100%,
    var(--ax) calc(100% - var(--ax)),
    calc(100% - var(--ax)) calc(100% - var(--ax)),
    calc(100% - var(--ax)) 100%,
    100% 100%,
    100% calc(100% - var(--ax)),
    calc(100% - var(--ax)) calc(100% - var(--ax)),
    calc(100% - var(--ax)) var(--ax),
    100% var(--ax),
    100% 0,
    calc(100% - var(--ax)) 0,
    calc(100% - var(--ax)) var(--ax),
    var(--ax) var(--ax)
  );
  transition: all 0.4s ease-in-out;
}

.luminous-card:hover {
  translate: 0 -0.2rem;
}

.luminous-card:hover::before {
  --offset: 0.5rem;
  --ax: 8rem;
  border-radius: 2.2rem;
  box-shadow: inset 0 0 0 0.08rem #fff1;
}

.luminous-light-layer {
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 100%;
  transform-style: preserve-3d;
  perspective: 400px;
  pointer-events: none;
}

.luminous-slit {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  width: 64%;
  height: 1.2rem;
  transform: rotateX(-76deg);
  background: #121212;
  box-shadow: 0 0 4px 0 #fff0;
  transition: all 0.4s ease-in-out;
}

.luminous-lumen {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  width: 100%;
  height: 100%;
  pointer-events: none;
  perspective: 400px;
  opacity: 0;
  transition: opacity 0.4s ease-in-out;
}

.luminous-lumen .min {
  width: 70%;
  height: 3rem;
  background: linear-gradient(#fff0, #fffa);
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 2.5rem;
  margin: auto;
  transform: rotateX(-42deg);
  opacity: 0.4;
}

.luminous-lumen .mid {
  width: 74%;
  height: 13rem;
  background: linear-gradient(#fff0, #fffa);
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 10em;
  margin: auto;
  transform: rotateX(-42deg);
  filter: blur(1rem);
  opacity: 0.8;
  border-radius: 100% 100% 0 0;
}

.luminous-lumen .hi {
  width: 50%;
  height: 13rem;
  background: linear-gradient(#fff0, #fffa);
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 12em;
  margin: auto;
  transform: rotateX(22deg);
  filter: blur(1rem);
  opacity: 0.6;
  border-radius: 100% 100% 0 0;
}

.luminous-darken {
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  bottom: 0;
  margin: auto;
  width: 100%;
  height: 100%;
  pointer-events: none;
  perspective: 400px;
  transition: opacity 0.4s ease-in-out;
  opacity: 0.5;
}

.luminous-darken > * {
  transition: opacity 0.4s ease-in-out;
}

.luminous-darken .sl {
  width: 64%;
  height: 10rem;
  background: linear-gradient(#000, #0000);
  position: absolute;
  left: 0;
  right: 0;
  top: 9.6em;
  bottom: 0;
  margin: auto;
  filter: blur(0.2rem);
  opacity: 0.1;
  border-radius: 0 0 100% 100%;
  transform: rotateX(-22deg);
}

.luminous-darken .ll {
  width: 62%;
  height: 10rem;
  background: linear-gradient(#000a, #0000);
  position: absolute;
  left: 0;
  right: 0;
  top: 11em;
  bottom: 0;
  margin: auto;
  filter: blur(0.8rem);
  opacity: 0.4;
  border-radius: 0 0 100% 100%;
  transform: rotateX(22deg);
}

.luminous-darken .slt {
  width: 0.5rem;
  height: 4rem;
  background: linear-gradient(#0005, #0000);
  position: absolute;
  left: 0;
  right: 11.5rem;
  top: 3.9em;
  bottom: 0;
  margin: auto;
  opacity: 0.6;
  border-radius: 0 0 100% 100%;
  transform: skewY(42deg);
}

.luminous-darken .srt {
  width: 0.5rem;
  height: 4rem;
  background: linear-gradient(#0005, #0000);
  position: absolute;
  right: 0;
  left: 11.5rem;
  top: 3.9em;
  bottom: 0;
  margin: auto;
  opacity: 0.6;
  border-radius: 0 0 100% 100%;
  transform: skewY(-42deg);
}

.luminous-content {
  position: relative;
  z-index: 1;
}

.luminous-icon {
  position: absolute;
  top: -13rem;
  left: 0;
  right: 0;
  margin: auto;
  width: fit-content;
  filter: drop-shadow(0 -1.2rem 1px transparent);
  transition: filter 0.4s ease-in-out;
}

.luminous-bottom {
  position: relative;
}

.luminous-title {
  margin: 0;
  margin-bottom: 1rem;
  font-size: 1.2rem;
  color: #fff;
