.screen-window {
  width: 100%;
  height: 270px;
  background: #f0f0f0;
  border: 1px solid #d0d0d0;
  border-radius: 4px;
  position: relative;
  overflow: hidden;
  box-shadow: inset 2px 2px 5px rgba(0, 0, 0, 0.05);
