}

.label {
  font-weight: 800;
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 10px;
  color: #666;
}

.freq-display {
  position: absolute;
  bottom: 20px;
  left: 0;
  width: 100%;
  height: 40px;
  border-top: 2px solid var(--text-dark);
