  align-items: center;
  justify-content: space-between;
  padding: 0 10px;
  font-family: monospace;
  font-size: 0.9rem;
}

.freq-needle {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 2px;
  height: 100%;
  background: var(--accent-orange);
  z-index: 5;
}

.tape-mechanism {
  display: flex;
  justify-content: center;
  gap: 30px;
  margin-top: 40px;
}

.spool {
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: #ddd;
  position: relative;
  border: 1px solid #bbb;
  overflow: hidden;
}

.spool::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: conic-gradient(
    #333 0deg,
    #333 120deg,
    transparent 120deg,
    transparent 180deg,
    #333 180deg,
    #333 300deg,
    transparent 300deg
  );
  border-radius: 50%;
}

.counter-box {
  background: #222;
  color: #fff;
  padding: 5px 10px;
  font-family: monospace;
  border-radius: 2px;
