  margin-top: 20px;
}

.waveform {
  width: 100%;
  height: 80px;
  display: flex;
  align-items: center;
  gap: 2px;
  margin-top: 20px;
}

.wave-bar {
  flex: 1;
  background: var(--text-dark);
  height: 10px;
  animation: equalize 1s ease-in-out infinite;
}

@keyframes equalize {
  0%,
  100% {
    height: 10px;
  }
  50% {
    height: 60px;
  }
}

.switch-row {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-top: 20px;
}

.toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 0.9rem;
  font-weight: 600;
}

.toggle-graphic {
  width: 40px;
  height: 20px;
  background: #ccc;
  border-radius: 10px;
  position: relative;
}
.toggle-graphic::after {
  content: "";
  position: absolute;
  top: 2px;
  left: 2px;
  width: 16px;
  height: 16px;
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);
}

.controls-strip {
