  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 5px;
  margin-bottom: 10px;
}

.push-btn {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: #f5f5f5;
  border: 1px solid #ddd;
  box-shadow:
    inset 0 0 5px rgba(255, 255, 255, 1),
    3px 3px 6px rgba(0, 0, 0, 0.1);
  cursor: pointer;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: all 0.1s;
  position: relative;
}

.push-btn::after {
  content: "";
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #e0e0e0;
  box-shadow: inset 1px 1px 2px rgba(0, 0, 0, 0.1);
}

.push-btn:active {
  box-shadow:
    inset 2px 2px 5px rgba(0, 0, 0, 0.1),
    1px 1px 2px rgba(0, 0, 0, 0.1);
  transform: translateY(1px);
}

.push-btn:active::after {
  background: var(--accent-orange);
}

.btn-label {
  position: absolute;
  bottom: -25px;
  font-size: 0.65rem;
  font-weight: 600;
  color: #888;
  text-transform: uppercase;
}

#app1:checked ~ .screen-window .tuner-band {
  transform: translateX(0%);
}
#app2:checked ~ .screen-window .tuner-band {
  transform: translateX(-25%);
}
#app3:checked ~ .screen-window .tuner-band {
  transform: translateX(-50%);
}
#app4:checked ~ .screen-window .tuner-band {
  transform: translateX(-75%);
}

