}

/* when folder is OPEN and you HOVER a file */
.folder-toggle:checked ~ .folder-container .file:hover .file-icon {
  color: rgba(255, 255, 255, 0.9);
}
.folder-toggle:checked ~ .folder-container .file-tag {
  opacity: 1;
}

