#tab-inv:checked ~ .pipboy-chassis .content-inv,
#tab-data:checked ~ .pipboy-chassis .content-data {
  display: flex;
}

#tab-stat:checked ~ .pipboy-chassis label[for="tab-stat"],
#tab-inv:checked ~ .pipboy-chassis label[for="tab-inv"],
#tab-data:checked ~ .pipboy-chassis label[for="tab-data"] {
  background-color: var(--pip-green);
  color: var(--bg-dark);
  text-shadow: none;
  box-shadow: 0 0 10px var(--pip-glow);
}

.content-stat {
