  flex-direction: column;
  gap: 15px;
}
.radar-container {
  position: relative;
  width: 160px;
  height: 160px;
  background: rgba(26, 255, 64, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  box-shadow: inset 0 0 20px var(--pip-glow);
  border: 2px solid var(--pip-green);
}
.radar-container::before {
  content: "";
  position: absolute;
  inset: 20px;
  background: rgba(26, 255, 64, 0.15);
  border-radius: 50%;
  border: 1px dashed rgba(26, 255, 64, 0.3);
}
.radar-container::after {
  content: "";
  position: absolute;
  width: 50px;
  height: 50px;
  background: rgba(26, 255, 64, 0.25);
  border-radius: 50%;
  border: 1px solid var(--pip-green);
}
.radar-container span {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  background: transparent;
  transform-origin: top left;
  animation: angularRotation 2s linear infinite;
  box-shadow: 6px -100px 40px -30px var(--pip-green);
  border-top: 2px solid var(--pip-green);
  z-index: 2;
}
.blip {
  position: absolute;
  width: 6px;
  height: 6px;
  background: #fff;
  border-radius: 50%;
  top: 35px;
  left: 100px;
  box-shadow:
    0 0 10px #fff,
    0 0 20px var(--pip-green);
  animation: blipFade 2s infinite;
  z-index: 3;
}

.radio-visualizer {
  display: flex;
  gap: 3px;
  align-items: flex-end;
  height: 15px;
  margin-left: 10px;
}
.bar {
  width: 4px;
  background-color: var(--pip-green);
  animation: eqBounce 1s infinite alternate;
}
.bar-1 {
  animation-delay: 0.1s;
}
.bar-2 {
  animation-delay: 0.3s;
}
.bar-3 {
  animation-delay: 0s;
}
.bar-4 {
  animation-delay: 0.4s;
}

@keyframes screenGlitch {
  0% {
    opacity: 0;
    filter: contrast(200%);
    transform: translateY(-2px);
    text-shadow:
      3px 0 rgba(255, 0, 0, 0.7),
      -3px 0 rgba(0, 0, 255, 0.7);
  }
  20% {
    opacity: 0.8;
    text-shadow:
      -3px 0 rgba(255, 0, 0, 0.7),
      3px 0 rgba(0, 0, 255, 0.7);
  }
  50% {
    opacity: 0.5;
    filter: contrast(150%) hue-rotate(20deg);
    transform: translateY(2px);
    text-shadow:
      2px 0 rgba(255, 0, 0, 0.7),
      -2px 0 rgba(0, 0, 255, 0.7);
  }
  100% {
    opacity: 1;
    filter: contrast(100%);
    transform: translateY(0);
    text-shadow: 0 0 4px var(--pip-glow);
  }
}

@keyframes crtScanline {
  0% {
    transform: translateY(-100%);
  }
  100% {
    transform: translateY(800%);
  }
}
@keyframes turnOnCRT {
  0% {
    transform: scale(1, 0.005);
    opacity: 0;
    filter: brightness(10);
  }
  30% {
    transform: scale(1, 0.005);
    opacity: 1;
    filter: brightness(5);
  }
  60% {
    transform: scale(1, 1);
    filter: brightness(2);
  }
  100% {
    transform: scale(1, 1);
    opacity: 1;
    filter: brightness(1);
  }
}
@keyframes angularRotation {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}
@keyframes radarSpin {
  100% {
    transform: rotate(360deg);
  }
}
@keyframes blipFade {
  0%,
  85% {
    opacity: 0;
  }
  90% {
    opacity: 1;
    transform: scale(1.5);
  }
  100% {
    opacity: 0;
  }
}
@keyframes eqBounce {
  0% {
    height: 3px;
  }
  100% {
    height: 15px;
  }
}
@keyframes blockPulse {
  0% {
    box-shadow: 0 0 15px var(--pip-glow);
  }
  100% {
    box-shadow: 0 0 35px var(--pip-glow);
  }
}
@keyframes blink {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}
@keyframes flicker {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.8;
  }
}
@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}

.blink-colon {
  animation: blink 1s step-end infinite;
}
.flicker-text {
  animation: flicker 0.15s infinite;
}
.flicker-fast {
  animation: flicker 0.08s infinite;
}
.pulse-icon {
  animation: pulse 1.5s infinite ease-in-out;
}

